"""BlitzAPI v2 search and enrichment, one documented request per operation.

Request models follow https://docs.blitz-api.ai/api-reference/v2.openapi.json
(version 2.0.0). POST operations perform searches/enrichment and may consume
records; no retries or automatic pagination are performed.
"""
from __future__ import annotations

from typing import Annotated, Literal, Optional, Union
from pydantic import BaseModel, ConfigDict, Field, FiniteFloat, StrictBool, StrictInt, StrictStr, field_validator
from nodes.core.base import NodeConfig, WorkflowNode
from nodes.core.connection_evidence import ConnectionEvidence
from nodes.core.credential_fields import clean_secret
from utils.ssrf import guarded_async_client

BASE_URL = "https://api.blitz-api.ai"
CREDENTIAL_TYPE = "blitz_api_key"


class BlitzAPIKeyCredential(BaseModel):
    model_config = ConfigDict(
        title="BlitzAPI API Key", extra="ignore", hide_input_in_errors=True,
        json_schema_extra={
            "x-credential-url": "https://app.blitz-api.ai",
            "x-credential-instructions": "Paste your BlitzAPI API key from the dashboard. NoClick sends it in the x-api-key header and verifies it with the free account key-info endpoint. Search and enrichment calls can consume records under your plan.",
        },
    )
    credential_type: Literal["blitz_api_key"] = Field("blitz_api_key", json_schema_extra={"ui:hidden": True})
    api_key: str = Field(..., min_length=1, max_length=4096, title="API key", json_schema_extra={"ui:widget": "password"})

    @field_validator("api_key", mode="before")
    @classmethod
    def key(cls, value):
        if not isinstance(value, str):
            raise ValueError("Paste a BlitzAPI API key")
        value = clean_secret(value, field_name="API key")
        if any(ch.isspace() for ch in value) or any(ord(ch) < 33 or ord(ch) > 126 for ch in value):
            raise ValueError("Paste the API key without a header prefix or whitespace")
        return value


class _Input(BaseModel):
    model_config = ConfigDict(extra="forbid", hide_input_in_errors=True)


class BlitzGetKeyInfoConfig(_Input):
    'Get API Key Details'
    operation: Literal['get_key_info'] = Field('get_key_info', json_schema_extra={"ui:hidden": True})


class BlitzSearchWaterfallIcpConfigCascadeItemLocationCity(_Input):
    include: Optional[list[Annotated[StrictStr, Field(min_length=1)]]] = Field([], max_length=10, description='Keywords to keep. A city matches when it has all the words of at least one keyword.', examples=[['Paris', 'London']])
    exclude: Optional[list[Annotated[StrictStr, Field(min_length=1)]]] = Field([], max_length=10, description='Keywords to drop. A person is removed when the city has all the words of any one keyword.', examples=[['Remote']])


class BlitzSearchWaterfallIcpConfigCascadeItemLocation(_Input):
    city: Optional[BlitzSearchWaterfallIcpConfigCascadeItemLocationCity] = Field(None, description='Keywords searched to find the city where the person is based')
    country_code: Optional[list[Annotated[StrictStr, Field(min_length=2, max_length=3)]]] = Field([], max_length=10, description='Country codes of the people to keep, such as `FR` or `GB`. Letter case does not matter.', examples=[['US', 'CA']])
    continent: Optional[list[Literal['Africa', 'Antarctica', 'Asia', 'Europe', 'North America', 'Oceania', 'South America']]] = Field([], max_length=10, description='Continents where the people live. A person matches when their location is on any of them.', examples=[['Europe']])
    sales_region: Optional[list[Literal['NORAM', 'LATAM', 'EMEA', 'APAC']]] = Field([], max_length=10, description='Sales regions where the people live. `NORAM` is North America, `LATAM` Latin America, `EMEA` Europe, Middle East and Africa, `APAC` Asia-Pacific.', examples=[['EMEA']])


class BlitzSearchWaterfallIcpConfigCascadeItem(_Input):
    include_title: list[StrictStr] = Field(..., min_length=1, max_length=50, description="Job title phrases to match, OR'd together (1 to 50). All words of a phrase must be in the title, in any order, as whole words, with no stemming or synonyms. Wrap a phrase in square brackets for an exact match. See [Keyword Filters](/guide/reference/normalization/filters).", examples=[['Marketing Director', 'Head Marketing', 'Chief Marketing Officer']])
    exclude_title: Optional[list[StrictStr]] = Field(None, max_length=50, description='Job title phrases that disqualify a person, with the same matching rules as `include_title` (up to 50). Also checked against the LinkedIn headline when `include_headline_search` is `true`.', examples=[['assistant', 'intern', 'junior']])
    location: Optional[BlitzSearchWaterfallIcpConfigCascadeItemLocation] = Field(None, description='Where the people of this tier live (not the company headquarters), with the same fields as `people.location` on Find People. A person must match every field you set. Leave it out (or send `{}`) to search the whole world. Each list takes at most 10 values; a longer list returns 422.')
    include_headline_search: Optional[StrictBool] = Field(False, description='When true, also matches the title phrases of this tier against the LinkedIn headline (not the About section). A person then matches when the headline or the job title matches. A headline match still needs a job at the company among the jobs that `include_active_jobs` and `include_past_jobs` select, so with `include_past_jobs: true` it can be a past job.', examples=[False])
    include_active_jobs: Optional[StrictBool] = Field(True, description='Search the current jobs of each person. The company and the title filters of this tier must hold in the same job. The matched job is returned in `experiences`, and `job_is_current` says whether it is current.', examples=[True])
    include_past_jobs: Optional[StrictBool] = Field(False, description='Also search the past jobs of each person. A person is returned once, with the matched job; a current job is preferred to a past one.', examples=[False])
    is_recent_hire: Optional[StrictBool] = Field(False, description='Only people whose job at the company started in the last 90 days, within this tier. It covers the jobs that include_active_jobs and include_past_jobs select (current jobs by default). The job must also match the title filters of this tier. A job with no start date never matches.', examples=[False])


class BlitzSearchWaterfallIcpConfig(_Input):
    'Waterfall ICP Search'
    operation: Literal['search_waterfall_icp'] = Field('search_waterfall_icp', json_schema_extra={"ui:hidden": True})
    company_linkedin_url: StrictStr = Field(..., examples=['https://www.linkedin.com/company/openai'])
    cascade: list[BlitzSearchWaterfallIcpConfigCascadeItem] = Field(..., min_length=1, max_length=10, description='Ordered list of search tiers (1 to 10). Tier 1 fills `max_results` first. If it finds fewer people than `max_results`, the next tier fills the slots that are left, and so on, until `max_results` is reached or no tiers are left. People already found in an earlier tier are not returned twice.')
    max_results: Optional[FiniteFloat] = Field(10, ge=1, le=100, description='Maximum number of results to return.', examples=[10])
    profile_min_connections: Optional[FiniteFloat] = Field(0, ge=0, description='Minimum number of LinkedIn connections a profile must have to be returned.', examples=[0])


