    industry: Optional[BlitzFindPeopleConfigCompanyIndustry] = Field(None, description='Exact matches for the industry search. `Unknown` matches a company with no industry on file, and a person with no company: in `include` it is added to the listed industries, in `exclude` it drops them.')
