    employee_range: Optional[list[Literal['1-10', '11-50', '51-200', '201-500', '501-1000', '1001-5000', '5001-10000', '10001+']]] = Field([], max_length=50, description='Exact matches for the employee range search', examples=[['1-10', '11-50', '51-200', '201-500', '501-1000', '1001-5000', '5001-10000', '10001+']])
    employee_count: Optional[BlitzFindPeopleConfigCompanyEmployeeCount] = Field(None, description="Range search on the company's employee count (the `employees_on_linkedin` value that Company Search returns)")
    min_linkedin_followers: Optional[FiniteFloat] = Field(0, ge=0, le=10000000, description='Minimum number of LinkedIn followers', examples=[0])
    revenue: Optional[BlitzFindPeopleConfigCompanyRevenue] = Field(None, description='Range search for company revenue (USD). Matches companies whose revenue band overlaps the requested range. 0 = unset.')
    naics_code: Optional[BlitzFindPeopleConfigCompanyNaicsCode] = Field(None, description='Exact matches for NAICS codes')
    sic_code: Optional[BlitzFindPeopleConfigCompanySicCode] = Field(None, description='Exact matches for SIC codes')
    mx: Optional[BlitzFindPeopleConfigCompanyMx] = Field(None, description='Mail provider of the company, from the MX records of its domains. Companies with no MX data are never matched by `include` and `exclude` never drops them, unless you use `any`.')
    web_traffic: Optional[BlitzFindPeopleConfigCompanyWebTraffic] = Field(None, description='Range search for total monthly web traffic (visits). 0 = unset.')
    ad_spend: Optional[BlitzFindPeopleConfigCompanyAdSpend] = Field(None, description='Range search for monthly Google ad spend (USD). `min` and `max` are inclusive; 0 = unset.')
    total_funding: Optional[BlitzFindPeopleConfigCompanyTotalFunding] = Field(None, description='Range search for total funding amount (USD). 0 = unset.')
    last_funding_amount: Optional[BlitzFindPeopleConfigCompanyLastFundingAmount] = Field(None, description='Range search for the last funding round amount (USD). 0 = unset.')
    last_funding_year: Optional[BlitzFindPeopleConfigCompanyLastFundingYear] = Field(None, description='Range search for the year of the last funding round. 0 = unset, otherwise 1800 to 2026.')
    last_funding_type: Optional[BlitzFindPeopleConfigCompanyLastFundingType] = Field(None, description='Exact matches for the last funding round type')
    lead_investors: Optional[BlitzFindPeopleConfigCompanyLeadInvestors] = Field(None, description='Keywords searched in lead investor names')
    keywords: Optional[BlitzFindPeopleConfigCompanyKeywords] = Field(None, description='Keywords searched across the company description, specialties, NAICS/SIC descriptions, and Crunchbase/G2 categories. A phrase matches a company if all its tokens are found within any one of those fields.')
