    title: Optional[BlitzSearchJobsConfigJobTitle] = Field(None, description='Keywords matched against the job title only (strict role search). Values match as a keyword search by default; wrap a value in square brackets (`"[Head of Sales]"`) to require an exact, case- and accent-insensitive match. See [Field normalization](/guide/reference/normalization/filters#exact-match-syntax).')
    description: Optional[BlitzSearchJobsConfigJobDescription] = Field(None, description='Keywords matched against the job description content')
    ai_keywords: Optional[BlitzSearchJobsConfigJobAiKeywords] = Field(None, description='Broad theme search across title, description, skills, responsibilities, requirements and taxonomies')
    field: Optional[BlitzSearchJobsConfigJobField] = Field(None, description="The job's professional field or discipline (e.g. Software Engineering, Sales, Finance). A job matches only when its whole field label is the value you send (case- and accent-insensitive).")
    seniority: Optional[BlitzSearchJobsConfigJobSeniority] = Field(None, description="The role's seniority, expressed as bands of required years of experience (0-2, 2-5, 5-10, 10+ years).")
    employment_type: Optional[BlitzSearchJobsConfigJobEmploymentType] = Field(None, description='The type of employment the job offers (full-time, part-time, contractor, temporary, intern, etc.).')
    work_arrangement: Optional[BlitzSearchJobsConfigJobWorkArrangement] = Field(None, description='Where the work is performed: on-site, hybrid, or remote.')
    location: Optional[BlitzSearchJobsConfigJobLocation] = Field(None, description='Job location (not company HQ).')
    date_posted: Optional[BlitzSearchJobsConfigJobDatePosted] = Field(None, description='Only jobs posted within the last N days')


