class BlitzAPIFullConfig(NodeConfig[BlitzAPIConfig, BlitzAPIKeyCredential]):
    model_config = ConfigDict(hide_input_in_errors=True)


OPERATIONS = {'get_key_info': ('GET', '/v2/account/key-info'), 'search_waterfall_icp': ('POST', '/v2/search/waterfall-icp-keyword'), 'find_employees': ('POST', '/v2/search/employee-finder'), 'find_people': ('POST', '/v2/search/people'), 'search_companies': ('POST', '/v2/search/companies'), 'find_tam_by_jobs': ('POST', '/v2/company/tam-by-jobs'), 'find_tam_by_people': ('POST', '/v2/company/tam-by-people'), 'search_jobs': ('POST', '/v2/jobs/search'), 'search_company_jobs': ('POST', '/v2/jobs/company'), 'enrich_person': ('POST', '/v2/enrichment/person'), 'find_work_email': ('POST', '/v2/enrichment/email'), 'find_phone': ('POST', '/v2/enrichment/phone'), 'find_person_by_email': ('POST', '/v2/enrichment/email-to-person'), 'find_person_by_phone': ('POST', '/v2/enrichment/phone-to-person'), 'enrich_company': ('POST', '/v2/enrichment/company'), 'domain_to_linkedin': ('POST', '/v2/enrichment/domain-to-linkedin'), 'linkedin_to_domain': ('POST', '/v2/enrichment/linkedin-to-domain'), 'get_current_date': ('POST', '/v2/utils/current-date'), 'company_distribution_by_country': ('POST', '/v2/enrichment/company-distribution-by-country'), 'company_distribution_by_department': ('POST', '/v2/enrichment/company-distribution-by-department')}


class BlitzAPINode(WorkflowNode):
    integration_type = "automation-blitz-api"
    connection_evidence = ConnectionEvidence(
        noun="BlitzAPI account", identity_operation="get_key_info", identity_keys=("id",),
    )

    @classmethod
    def get_config_model(cls):
        return BlitzAPIFullConfig

    async def execute(self, inputs):
        if not isinstance(self.config, BlitzAPIFullConfig) or self.config.credentials is None:
            raise ValueError("Connect a BlitzAPI API key")
        config = self.config.config
        key = self.config.credentials.api_key
        method, path = OPERATIONS[config.operation]
        body = config.model_dump(mode="json", exclude={"operation"}, exclude_none=True)
        # Static provider origin; never follow provider redirects with credentials.
        async with guarded_async_client(timeout=60, trust_env=False, follow_redirects=False) as client:
            response = await client.request(
                method, BASE_URL + path,
                headers={"x-api-key": key, "Accept": "application/json"},
                **({"json": body} if method == "POST" else {}),
            )
        if len(response.content) > 10_000_000:
            raise ValueError("BlitzAPI response exceeds 10 MB")
        if response.status_code != 200:
            message = "Request was not accepted"
            try:
                error = response.json()
                if isinstance(error, dict) and isinstance(error.get("message"), str):
                    message = error["message"][:1000].replace(key, "[redacted]")
            except ValueError:
                pass
            # Preserve the status and provider's error for the shared connect verdict.
            raise ValueError(f"BlitzAPI HTTP {response.status_code}: {message}")
        if response.headers.get("content-type", "").split(";", 1)[0].strip().lower() != "application/json":
            raise ValueError("BlitzAPI did not return JSON")
        data = response.json()
        if not isinstance(data, dict) or data.get("success") is False or data.get("blocked") is True:
            raise ValueError("BlitzAPI did not confirm the request")
        if config.operation == "get_key_info":
            if data.get("valid") is not True:
                raise ValueError("BlitzAPI 401: API key is not valid")
            if not isinstance(data.get("id"), str) or not data["id"]:
                raise ValueError("BlitzAPI key-info response has no account key ID")
        # Keep the documented envelope (found=false is a successful no-match),
        # including cursors and fair_usage. Callers explicitly request each page.
        return {"status": "success", "operation": config.operation, "data": _redact(data, key)}


def _redact(value, key):
    if isinstance(value, str):
        return value.replace(key, "[redacted]")
    if isinstance(value, list):
        return [_redact(item, key) for item in value]
    if isinstance(value, dict):
        return {str(k).replace(key, "[redacted]"): _redact(v, key) for k, v in value.items()}
    return value
